{"command":"D="/home/user/deepseek-harness/.claude/worktrees/agent-ac95992e601dc9bf3/.code-safety/NodeGoat-misses-a/repo/program-5ed00b9dfaf535843096243b51ed4dbc1172217012071066eea7933eb96783d0/@integration"
cd "$D"
node -e '
const fs = require("fs");
const union = JSON.parse(fs.readFileSync("findings.json","utf8"));
const order = ["critical","high","medium","low","info"];
let out = [];
for (const sev of order) {
  out.push(`### ${sev}`);
  out.push("");
  for (const f of union) {
    if (f.severity !== sev) continue;
    const loc = f.endLine ? `${f.file}:${f.line}-${f.endLine}` : `${f.file}:${f.line}`;
    out.push(`- \`${f.id}\` — ${f.title} (\`${loc}\`, ${f.cwe}, ${f.confidence})`);
  }
  out.push("");
}
fs.writeFileSync("/tmp/findings_section.md", out.join("\n"));
console.log("done");
'
cat /tmp/findings_section.md | head -100","description":"Generate Findings section markdown grouped by severity"}

